def gen(rng):
    sizes = [10 ** (5 - k) * 26 ** k for k in range(6)]
    starts = []
    acc = 0
    for s in sizes:
        starts.append(acc + 1)
        acc += s
    total = acc
    tests = [str(n) for n in (1, 2, 3, 99999, 100000, 100001, 100002, 110000, 110001, 360000, 360001, 360002, total, total - 1)]
    for k in range(1, 6):
        st = starts[k]
        end = st + sizes[k] - 1
        for n in (st, st + 1, st + 10 ** (5 - k) - 1, st + 10 ** (5 - k), end - 1, end):
            tests.append(str(n))
    for _ in range(25):
        tests.append(str(rng.randint(1, 3000)))
    for _ in range(10):
        tests.append(str(rng.randint(1, 400000)))
    for _ in range(6):
        tests.append(str(rng.randint(1, total)))
    tests.append(str(total))
    tests.append(str(total - 123456))
    return tests

